   lab.querySelector('[data-window-result="flight"]').textContent=flight+" KB";lab.querySelector('[data-window-result="window-rate"]').textContent=windowRate.toFixed(1)+" Mbps";lab.querySelector('[data-window-result="rate"]').textContent=rate.toFixed(1)+" Mbps";
