 function bindIpLab(l){const input=l.querySelector("[data-ip-destination]"),rows=[...l.querySelectorAll("[data-prefix]")],s=l.querySelector("[data-ip-status]");function parse(ip){const a=ip.trim().split(".");if(a.length!==4||a.some(x=>!/^\d{1,3}$/.test(x)||Number(x)>255))return null;return a.reduce((n,x)=>(n<<8n)|BigInt(x),0n)}function update(){const address=parse(input.value);rows.forEach(r=>r.classList.remove("is-match"));if(address===null){s.textContent="Enter a valid IPv4 address with four decimal octets.";return}let win=null,best=-1;for(const row of rows){const [base,p]=row.dataset.prefix.split("/"),bits=Number(p),net=parse(base),mask=bits===0?0n:((0xffffffffn<<(32n-BigInt(bits)))&0xffffffffn);if((address&mask)===(net&mask)&&bits>best){win=row;best=bits}}if(win){win.classList.add("is-match");const c=win.children;s.textContent="Longest match: "+c[0].textContent+" → "+c[1].textContent+" via "+c[2].textContent+"."}else s.textContent="No route matches this address."}input.addEventListener("input",update);update()}
