 function bindParity(l){const input=l.querySelector("[data-parity-bits]"),flip=l.querySelector("[data-parity-flip]"),d=l.querySelector("[data-parity-diagram]"),s=l.querySelector("[data-parity-status]");let corrupted=false;function update(){const bits=input.value.trim();if(!/^[01]{8}$/.test(bits)){s.textContent="Enter exactly eight bits using only 0 and 1.";d.textContent="";return}const ones=[...bits].filter(x=>x==="1").length,parity=ones%2,received=corrupted?bits.slice(0,3)+(bits[3]==="1"?"0":"1")+bits.slice(4):bits,receivedOnes=[...received].filter(x=>x==="1").length,valid=(receivedOnes+parity)%2===0;d.innerHTML='<div class="network-node">Received data '+received+'<small>sender parity '+parity+'</small></div><span class="network-arrow">→</span><div class="network-node">Receiver<small>even parity check</small></div>';s.textContent=valid?"Receiver check passes: total number of 1s is even.":"Receiver detects corruption: transmitted parity no longer matches the received data."}input.addEventListener("input",()=>{corrupted=false;update()});flip.addEventListener("click",()=>{if(/^[01]{8}$/.test(input.value.trim())){corrupted=!corrupted;update()}});update()}function bindAccess(l){const mode=l.querySelector("[data-access-mode]"),count=l.querySelector("[data-access-count]"),s=l.querySelector("[data-access-status]");function update(){const n=Number(count.value),m=mode.value;s.textContent=m==="random"?n+" senders share one contention pool. Backoff reduces repeated collisions, but more active senders mean more waiting and retries.":m==="partition"?"Channel capacity is divided among "+n+" senders. Collision risk is low, but idle senders leave their reserved share unused.":"A coordinator grants turns to "+n+" senders. This improves orderly access but adds scheduling delay and coordination overhead."}mode.addEventListener("change",update);count.addEventListener("input",update);update()}
 function bindSwitch(l){let step=0;const s=l.querySelector("[data-switch-status]"),rows=[...l.querySelectorAll("[data-switch-entry]")],msg=["Laptop broadcasts ARP: who has the gateway IP? Switch floods the broadcast within this VLAN.","Gateway replies with its MAC. Switch learns the gateway source MAC on port 2.","Laptop sends an Ethernet frame to the known gateway MAC. Switch forwards it only to port 2."];function paint(){s.textContent=msg[step];rows.forEach(r=>r.classList.toggle("is-match",step>0&&r.dataset.switchEntry===(step===1?"gateway":"laptop")))}l.querySelector("[data-switch-next]").addEventListener("click",()=>{step=Math.min(2,step+1);paint()});l.querySelector("[data-switch-reset]").addEventListener("click",()=>{step=0;paint()});paint()}
