 function bindLanTrace(page){if(page.querySelector("[data-lan-trace]"))return;page.insertAdjacentHTML("beforeend",`<section class="lan-trace" data-lan-trace aria-label="Interactive guide to delivery within a LAN"><header><div><p class="lan-kicker">VISUAL GUIDE · SAME-SUBNET DELIVERY</p><h3>What happens inside a LAN?</h3></div><p class="lan-kicker">SELECT A STEP</p></header><div class="lan-tabs" role="tablist" aria-label="LAN delivery steps"><button class="lan-tab is-active" role="tab" aria-selected="true" data-lan-step="0"><b>01</b>Local?</button><button class="lan-tab" role="tab" aria-selected="false" data-lan-step="1"><b>02</b>ARP</button><button class="lan-tab" role="tab" aria-selected="false" data-lan-step="2"><b>03</b>Frame</button><button class="lan-tab" role="tab" aria-selected="false" data-lan-step="3"><b>04</b>Switch</button><button class="lan-tab" role="tab" aria-selected="false" data-lan-step="4"><b>05</b>Deliver</button></div><div class="lan-trace-body"><div class="lan-topology"><span class="lan-link a"></span><span class="lan-link b"></span><span class="lan-link c"></span><span class="lan-packet" aria-hidden="true"></span><div class="lan-node laptop"><i></i><strong>Laptop</strong><small>192.168.1.10</small></div><div class="lan-node switch"><i></i><strong>Switch</strong><small>MAC table</small></div><div class="lan-node server"><i></i><strong>Local server</strong><small>192.168.1.24</small></div><div class="lan-node router"><i></i><strong>Gateway</strong><small>192.168.1.1</small></div></div><div class="lan-explain"><p class="lan-kicker" data-lan-kicker>STEP 01 · IP DECISION</p><h4 data-lan-title>Is the server local?</h4><p data-lan-copy>The laptop applies its subnet mask. 192.168.1.24 is in the same 192.168.1.0/24 network, so it can deliver directly to the server rather than to the router.</p><div class="lan-facts"><div><span>Data unit</span><strong data-lan-unit>IP datagram</strong></div><div><span>Key idea</span><strong data-lan-key>Same subnet</strong></div></div></div></div><div class="lan-wire"><div><span>Destination IP</span><code>192.168.1.24</code></div><div><span data-lan-wire-label>Next</span><code data-lan-mac>Need ARP first</code></div></div><p class="lan-contrast"><b>If the server were remote:</b> the destination IP would still be the server, but the destination MAC would be the <b>default gateway</b>, which is the next local hop.</p></section>`);const steps=[{k:"STEP 01 · IP DECISION",t:"Is the server local?",c:"The laptop applies its subnet mask. 192.168.1.24 is in the same 192.168.1.0/24 network, so it can deliver directly to the server rather than to the router.",u:"IP datagram",key:"Same subnet",m:"Need ARP first",w:"NEXT",a:["laptop"]},{k:"STEP 02 · ARP",t:"Who has 192.168.1.24?",c:"The laptop broadcasts an ARP request. The local server replies with its MAC address. ARP maps a local IP next hop to its Ethernet delivery address.",u:"ARP request / reply",key:"IP → MAC",m:"Broadcast, then 3C:88:…:24",w:"ARP",a:["laptop","switch","server"],motion:"reply"},{k:"STEP 03 · ETHERNET",t:"Put the datagram in a frame.",c:"The laptop wraps the unchanged IP datagram in an Ethernet frame whose destination MAC is the server’s MAC. This frame is valid for this one LAN hop.",u:"Ethernet frame",key:"Encapsulation",m:"3C:88:…:24",w:"FRAME",a:["laptop"]},{k:"STEP 04 · FORWARDING",t:"The switch chooses an output port.",c:"The switch learns the laptop’s source MAC on the ingress port, looks up the server’s destination MAC, and forwards the frame only to the server’s port.",u:"Ethernet frame",key:"MAC-table lookup",m:"3C:88:…:24",w:"FORWARD",a:["switch"],motion:"forward"},{k:"STEP 05 · DELIVERY",t:"The local server receives it.",c:"The server accepts the frame addressed to its MAC, removes the Ethernet header, and passes the IP datagram upward. The application can receive the request.",u:"Application message",key:"Decapsulation",m:"3C:88:…:24",w:"DELIVER",a:["server"],motion:"forward"}];const root=page.querySelector("[data-lan-trace]"),topology=root.querySelector(".lan-topology"),nodes=[...root.querySelectorAll(".lan-node")],tabs=[...root.querySelectorAll("[data-lan-step]")];const show=i=>{const s=steps[i];tabs.forEach((b,n)=>{b.classList.toggle("is-active",n===i);b.setAttribute("aria-selected",String(n===i))});root.querySelector("[data-lan-kicker]").textContent=s.k;root.querySelector("[data-lan-title]").textContent=s.t;root.querySelector("[data-lan-copy]").textContent=s.c;root.querySelector("[data-lan-unit]").textContent=s.u;root.querySelector("[data-lan-key]").textContent=s.key;root.querySelector("[data-lan-mac]").textContent=s.m;root.querySelector("[data-lan-wire-label]").textContent=s.w;nodes.forEach(n=>{const on=s.a.includes([...n.classList].find(x=>["laptop","switch","server","router"].includes(x)));n.classList.toggle("is-active",on);n.classList.toggle("is-muted",!on)});topology.dataset.motion="";requestAnimationFrame(()=>topology.dataset.motion=s.motion||"")};tabs.forEach((b,i)=>{b.addEventListener("click",()=>show(i));b.addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight"].includes(e.key))return;e.preventDefault();const n=(i+(e.key==="ArrowRight"?1:-1)+tabs.length)%tabs.length;tabs[n].focus();show(n)})});show(0)}
 function bindWireless(l){const d=l.querySelector("[data-radio-distance]"),n=l.querySelector("[data-radio-noise]"),out=l.querySelector("[data-radio-diagram]"),s=l.querySelector("[data-radio-status]");function update(){const quality=11-Number(d.value)-Number(n.value);out.innerHTML='<div class="network-node">Device<small>transmit</small></div><span class="network-arrow">→</span><div class="network-node">Access point<small>receive</small></div>';s.textContent="Illustrative link margin: "+quality+". "+(quality>=6?"Strong margin: higher-rate decoding is more likely.":quality>=2?"Moderate margin: rate adaptation or retries may appear.":"Weak margin: expect more errors, retries, or loss; reduce distance or interference.")}d.addEventListener("input",update);n.addEventListener("input",update);update()}
